function makeLearningData(list){
  return list.map(x=>{
    if(x.source==='Curated') return addCuratedContent(x);
    return addImportedContent(x);
  });
}
function addImportedContent(x){
  const q=x.jp;
  x.examples=[
    {jp:`この製品では、${q}が重要です。`,en:`${x.en} is important for this product.`},
    {jp:`設計時には、${q}について確認します。`,en:`During design, we check the ${x.en.toLowerCase()}.`}
  ];
  x.coll=[
    [`${q}を確認する`,``, `check ${x.en}`],
    [`${q}を評価する`,``, `evaluate ${x.en}`],
    [`${q}について検討する`,``, `consider ${x.en}`],
    [`${q}に関する情報`,``, `information about ${x.en}`],
    [`${q}の条件`,``, `conditions for ${x.en}`]
  ];
  return x;
}
function addCuratedContent(x){
  const j=x.jp;
  const map={
    '設計':[['製品を設計する','せいひんをせっけいする','design a product'],['設計条件','せっけいじょうけん','design conditions'],['設計変更','せっけいへんこう','design change'],['設計段階','せっけいだんかい','design stage'],['設計意図','せっけいいと','design intent']],
    '図面':[['図面を確認する','ずめんをかくにんする','check the drawing'],['図面を修正する','ずめんをしゅうせいする','revise the drawing'],['図面を作成する','ずめんをさくせいする','create a drawing'],['図面番号','ずめんばんごう','drawing number'],['最新図面','さいしんずめん','latest drawing']],
    '寸法':[['寸法を測定する','すんぽうをそくていする','measure dimensions'],['寸法を確認する','すんぽうをかくにんする','check dimensions'],['寸法公差','すんぽうこうさ','dimensional tolerance'],['寸法変更','すんぽうへんこう','dimension change'],['寸法精度','すんぽうせいど','dimensional accuracy']],
    '材質':[['材質を選定する','ざいしつをせんていする','select a material'],['材質を確認する','ざいしつをかくにんする','check the material'],['材質変更','ざいしつへんこう','material change'],['材質特性','ざいしつとくせい','material properties'],['使用環境に適した材質','しようかんきょうにてきしたざいしつ','material suitable for the use environment']],
    '強度':[['強度を評価する','きょうどをひょうかする','evaluate strength'],['強度解析を行う','きょうどかいせきをおこなう','perform strength analysis'],['必要強度','ひつようきょうど','required strength'],['強度不足','きょうどぶそく','insufficient strength'],['強度を確保する','きょうどをかくほする','ensure strength']],
    '剛性':[['剛性を確保する','ごうせいをかくほする','ensure stiffness'],['剛性を評価する','ごうせいをひょうかする','evaluate stiffness'],['剛性不足','ごうせいぶそく','insufficient stiffness'],['必要剛性','ひつようごうせい','required stiffness'],['構造剛性','こうぞうごうせい','structural stiffness']],
    '応力':[['応力を計算する','おうりょくをけいさんする','calculate stress'],['応力集中','おうりょくしゅうちゅう','stress concentration'],['最大応力','さいだいおうりょく','maximum stress'],['許容応力','きょようおうりょく','allowable stress'],['応力分布','おうりょくぶんぷ','stress distribution']],
    '流路':[['流路を設計する','りゅうろをせっけいする','design the flow path'],['流路断面積','りゅうろだんめんせき','flow-path cross-sectional area'],['流路抵抗','りゅうろていこう','flow-path resistance'],['流路を改善する','りゅうろをかいぜんする','improve the flow path'],['流路形状','りゅうろけいじょう','flow-path geometry']],
    '圧力':[['圧力を測定する','あつりょくをそくていする','measure pressure'],['圧力を調整する','あつりょくをちょうせいする','adjust pressure'],['圧力変化','あつりょくへんか','pressure change'],['圧力条件','あつりょくじょうけん','pressure conditions'],['圧力損失','あつりょくそんしつ','pressure loss']],
    'モーター':[['モーターを設計する','もーたーをせっけいする','design a motor'],['モーター性能','もーたーせいのう','motor performance'],['モーター回転数','もーたーかいてんすう','motor speed'],['モーター出力','もーたーしゅつりょく','motor output'],['モーター効率','もーたーこうりつ','motor efficiency']],
    'トルク':[['トルクを測定する','とるくをそくていする','measure torque'],['最大トルク','さいだいとるく','maximum torque'],['必要トルク','ひつようとるく','required torque'],['トルク特性','とるくとくせい','torque characteristics'],['トルクを確保する','とるくをかくほする','ensure sufficient torque']],
    '振動':[['振動を測定する','しんどうをそくていする','measure vibration'],['振動を抑える','しんどうをおさえる','suppress vibration'],['振動試験','しんどうしけん','vibration test'],['振動解析','しんどうかいせき','vibration analysis'],['振動特性','しんどうとくせい','vibration characteristics']],
    '不具合':[['不具合を調査する','ふぐあいをちょうさする','investigate a defect'],['不具合の原因','ふぐあいのげんいん','cause of the defect'],['不具合を修正する','ふぐあいをしゅうせいする','fix the defect'],['不具合を再現する','ふぐあいをさいげんする','reproduce the defect'],['不具合対応','ふぐあいたいおう','defect handling']],
    'リスク':[['リスクを評価する','りすくをひょうかする','evaluate risk'],['リスクを低減する','りすくをていげんする','reduce risk'],['リスク分析','りすくぶんせき','risk analysis'],['残留リスク','ざんりゅうりすく','residual risk'],['リスク管理','りすくかんり','risk management']],
    '検証':[['設計を検証する','せっけいをけんしょうする','verify the design'],['検証試験','けんしょうしけん','verification test'],['検証結果','けんしょうけっか','verification result'],['検証計画','けんしょうけいかく','verification plan'],['検証記録','けんしょうきろく','verification record']]
  };
  x.coll=map[j]||[[`${j}を確認する`,``, `check ${x.en}`],[`${j}を評価する`,``,`evaluate ${x.en}`],[`${j}を測定する`,``,`measure ${x.en}`],[`${j}を改善する`,``,`improve ${x.en}`],[`${j}に関する情報`,``,`information about ${x.en}`]];
  x.examples=[
    {jp:`設計[せっけい]段階[だんかい]で${j}を確認[かくにん]します。`,en:`We check ${x.en} at the design stage.`},
    {jp:`必要[ひつよう]な${j}を評価[ひょうか]して、結果[けっか]を記録[きろく]します。`,en:`We evaluate the required ${x.en} and record the results.`}
  ];
  return x;
}
BASE_DATA = makeLearningData(BASE_DATA);

